package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** First simple RSE actuator: visible output brightness follows incoming Redstone 0..15. */
public class AnalogIndicatorBlock extends Block{public static final IntegerProperty LEVEL=IntegerProperty.create("level",0,15);public AnalogIndicatorBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(LEVEL,0));}@Override public MapCodec<AnalogIndicatorBlock> codec(){return RedstoneEngineering.ANALOG_INDICATOR_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(LEVEL);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(!l.isClientSide)update(l,p,s);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(!l.isClientSide)update(l,p,s);}@Override public boolean canConnectRedstone(BlockState s,net.minecraft.world.level.BlockGetter l,BlockPos p,net.minecraft.core.Direction d){return true;}private void update(Level l,BlockPos p,BlockState s){int v=Math.max(0,Math.min(15,l.getBestNeighborSignal(p)));if(v!=s.getValue(LEVEL))l.setBlock(p,s.setValue(LEVEL,v),Block.UPDATE_CLIENTS);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Analog Indicator actuator = "+s.getValue(LEVEL)+"/15 brightness"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
